//! 原制約の独立成分に目的上限制約を加え、既存Repairだけで主解を改善する診断。
use mip_codex::{heuristic::Repair,model::{Model,Row},solve::Result};
use std::{collections::HashMap,fs::File,time::{Instant,Duration}};
fn find(p:&mut[usize],i:usize)->usize{if p[i]!=i{p[i]=find(p,p[i]);}p[i]}
fn improve(m:&Model,seed:&[f64],end:Instant)->(Vec<f64>,usize){
 let lower:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let upper:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let mut x=seed.to_vec();let mut work=m.clone();work.rows.push(Row{name:"diagnostic_objective_cut".into(),lower:None,upper:None,coefficients:(0..m.variables.len()).map(|j|(j,1.)).collect(),exact_integral:true,exact_coefficients:true,exact_coefficient_flags:Vec::new(),lower_enclosure:None,upper_enclosure:None});let mut improvements=0;
 for turn in 0..10000u64{if Instant::now()>=end{break;}let target=m.objective(&x)-1.;let r=work.rows.last_mut().unwrap();r.upper=Some(target);r.upper_enclosure=Some([target,target]);let mut repair=Repair::new(&work);let level=(turn/2)%4;let on=[0.99,0.95,0.90,0.80][level as usize];let off=[0.0001,0.0005,0.001,0.002][level as usize];let point:Vec<_>=x.iter().map(|&v|if turn<2{v}else if v>0.5{on}else{off}).collect();let deadline=end.min(Instant::now()+Duration::from_millis(100));if let Some(v)=repair.search(&point,&lower,&upper,deadline,100_000_000,turn){assert!(Repair::new(m).candidate_check(&v));assert!(m.objective(&v)<m.objective(&x));x=v;improvements+=1;}}
 (x,improvements)
}
fn main(){
 let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mip_codex::mps::read(&a[1]).unwrap();assert!(!m.maximize&&m.offset==0.&&m.variables.iter().all(|v|v.integer&&v.lower==Some(0.)&&v.upper==Some(1.)&&v.objective==1.));let input:serde_json::Value=serde_json::from_reader(File::open(&a[2]).unwrap()).unwrap();let mut x:Vec<_>=m.variables.iter().map(|v|input["values"][&v.name].as_f64().unwrap()).collect();assert!(Repair::new(&m).candidate_check(&x));let start=Instant::now();let seconds:f64=a[3].parse().unwrap();let end=start+Duration::from_secs_f64(seconds);let n=m.variables.len();let mut parent:Vec<_>=(0..n).collect();let mut sizes=vec![1usize;n];
 for r in &m.rows{if r.lower.is_none()&&r.upper.is_none(){continue;}if let Some(&(first,_))=r.coefficients.iter().find(|&&(_,v)|v!=0.){for &(j,v)in &r.coefficients{if v==0.{continue;}let mut u=find(&mut parent,first);let mut w=find(&mut parent,j);if u!=w{if sizes[u]<sizes[w]{std::mem::swap(&mut u,&mut w);}parent[w]=u;sizes[u]+=sizes[w];}}}}
 let roots:Vec<_>=(0..n).map(|j|find(&mut parent,j)).collect();let mut groups=HashMap::<usize,Vec<usize>>::new();for(j,&r)in roots.iter().enumerate(){groups.entry(r).or_default().push(j);}let mut rowgroups=HashMap::<usize,Vec<usize>>::new();for(i,r)in m.rows.iter().enumerate(){if r.lower.is_none()&&r.upper.is_none(){continue;}if let Some(&(j,_))=r.coefficients.iter().find(|&&(_,v)|v!=0.){rowgroups.entry(roots[j]).or_default().push(i);}}
 let mut groups:Vec<_>=groups.into_iter().filter(|(r,_)|rowgroups.contains_key(r)).collect();groups.sort_by_key(|(r,g)|(std::cmp::Reverse(g.len()),*r));let mut remaining=groups.len();let mut inverse=vec![usize::MAX;n];let mut records=Vec::new();
 for(root,columns)in groups{if Instant::now()>=end{break;}for(k,&j)in columns.iter().enumerate(){inverse[j]=k;}let sub=Model{name:format!("component-{root}"),maximize:false,offset:0.,offset_enclosure:Some([0.,0.]),original_decimal:m.original_decimal,variables:columns.iter().map(|&j|m.variables[j].clone()).collect(),rows:rowgroups[&root].iter().map(|&i|{let mut r=m.rows[i].clone();r.coefficients=r.coefficients.iter().map(|&(j,v)|{assert_eq!(roots[j],root);(inverse[j],v)}).collect();r}).collect()};let seed:Vec<_>=columns.iter().map(|&j|x[j]).collect();let localend=end.min(Instant::now()+end.saturating_duration_since(Instant::now())/remaining as u32);let before=sub.objective(&seed);let(v,count)=improve(&sub,&seed,localend);for(k,&j)in columns.iter().enumerate(){x[j]=v[k];}assert!(Repair::new(&m).candidate_check(&x));records.push(serde_json::json!({"root":root,"variables":columns.len(),"before":before,"after":sub.objective(&v),"improvements":count,"seconds":start.elapsed().as_secs_f64()}));remaining-=1;
 }
 let result=Result{status:"feasible_component_objective_cut_diagnostic".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(&x).map(|(v,&x)|(v.name.clone(),x)).collect()),seconds:start.elapsed().as_secs_f64(),..Result::default()};serde_json::to_writer(File::create(&a[4]).unwrap(),&result).unwrap();println!("{}",serde_json::json!({"objective":result.objective,"seconds":result.seconds,"components":records}));
}
